<?php require_once __DIR__.'/bootstrap.php';$secret=(string)getenv('ADMIN_SETUP_KEY');if($secret===''||!hash_equals($secret,(string)($_POST['setup_key']??''))){page_start('Admin setup');?><div class="panel" style="max-width:520px;margin:auto"><h1>Initial administrator setup</h1><p>Set a strong ADMIN_SETUP_KEY in Render first. This page works only until the first admin account is created.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Setup key</label><input type="password" name="setup_key" required><label>Admin name</label><input name="name" required><label>Admin email</label><input type="email" name="email" required><label>Password (12+ characters)</label><input type="password" name="password" minlength="12" required><button>Create admin</button></form></div><?php page_end();exit;}verify_csrf();$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();if($count>0){http_response_code(410);exit('An admin already exists. Remove ADMIN_SETUP_KEY from Render.');}$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12){http_response_code(400);exit('Invalid name, email, or password.');}$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);unset($_SESSION['csrf']);header('Location: login.php');exit;?>
